import json
import requests
import chardet
API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    response = requests.get(url, timeout=5)
    content = response.content
    if not content:
        return {}
    if from_encoding is None:
        detected = chardet.detect(content)
        from_encoding = detected.get('encoding')
        if from_encoding is None:
            raise ValueError("Unable to detect encoding for non-empty content")
    decoded = content.decode(from_encoding)
    reencoded = decoded.encode(to_encoding)
    return json.loads(reencoded)

import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if not isinstance(webpage_url, str) or not webpage_url:
        raise ValueError("Invalid URL provided.")
    try:
        response = requests.get(webpage_url)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Network issue accessing URL: {e}")
    try:
        tree = html.fromstring(response.content)
        table = tree.xpath('//table')[0]
    except IndexError:
        return 0
    headers = [th.text_content().strip() for th in table.xpath('.//th')]
    rows = []
    for tr in table.xpath('.//tr'):
        cols = tr.xpath('.//td')
        if cols:
            rows.append([td.text_content().strip() for td in cols])
    if not rows:
        return 0
    df = pd.DataFrame(rows, columns=headers if headers else None)
    try:
        conn = sqlite3.connect(database_name)
        df.to_sql('my_table', conn, if_exists='replace', index=False)
        conn.commit()
        row_count = len(df)
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")
    return row_count

import requests
import logging
def task_func(repo_url: str) -> dict:
    if not repo_url or not isinstance(repo_url, str):
        raise ValueError("Repository URL must be a non-empty string.")
    try:
        response = requests.get(repo_url, timeout=10)
        if response.status_code == 403 or response.status_code == 429:
            raise requests.exceptions.HTTPError(f"GitHub API rate limit exceeded: {response.reason}")
        response.raise_for_status()
        repo_info = response.json()
        open_issues = repo_info.get('open_issues_count', 0)
        if open_issues > 100:
            logging.warning(f"Repository has {open_issues} open issues, which exceeds the threshold of 100.")
        return repo_info
    except requests.exceptions.HTTPError as e:
        raise requests.exceptions.HTTPError(f"HTTP error occurred: {e}")
    except requests.exceptions.RequestException as e:
        raise requests.exceptions.RequestException(f"Request failed: {e}")

