import seaborn as sns
HEADERS = {'accept': 'application/json'}
def task_func(url, parameters):
    if not url or not parameters:
        raise Exception("URL and parameters must be provided.")
    try:
        response = requests.get(url, params=parameters, headers=HEADERS)
        response.raise_for_status()
        data = response.json()
    except Exception as e:
        raise Exception(f"Failed to retrieve data: {e}")
    if not data:
        raise Exception("Empty data received.")
    try:
        df = pd.DataFrame(data)
    except Exception as e:
        raise Exception(f"Invalid data format: {e}")
    if df.empty:
        raise Exception("DataFrame is empty.")
    numeric_df = df.select_dtypes(include=['number'])
    if numeric_df.empty:
        raise Exception("No numerical columns found for correlation.")
    corr = numeric_df.corr()
    ax = sns.heatmap(corr, annot=True, cmap='coolwarm')
    return (df, ax)

